import * as THREE from 'three';

// Visualize vertices as individual points
<points>
  {/* Each vertex is rendered as a small point */}
  <pointsMaterial 
    size={0.05}      // Size of each point
    color="#10b981" // Green color
    sizeAttenuation // Points get smaller with distance
  />
</points>

import { Edges } from '@react-three/drei';

// Visualize edges (lines connecting vertices)
<mesh>
  <cylinderGeometry args={[0.6, 0.6, 2, 32]} />

  {/* Invisible material - we only want to see edges */}
  <meshBasicMaterial transparent opacity={0} />

  {/* Edges component renders the wireframe */}
  <Edges color="#3b82f6" threshold={0} />
</mesh>

import { Edges } from '@react-three/drei';

// Combine faces (surfaces) with edges for a complete 3D object
<mesh>
  <cylinderGeometry args={[0.6, 0.6, 2, 32]} />

  {/* Material with metallic properties for the surface */}
  <meshStandardMaterial
    color="#14b8a6"
    metalness={0.8}
    roughness={0.2}
  />

  {/* Overlay edges to show the wireframe structure */}
  <Edges color="#000000" threshold={0} />
</mesh>

